export function OptimisticUI({
  outcome = "{{outcome}}",
  confirmed = {{confirmed}},
  itemLabel = "{{itemLabel}}",
  accent = "{{accent}}",
}) {
  return (
    <div style={{ width: "100%", maxWidth: 320, padding: 16, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, fontFamily: "system-ui, sans-serif", fontSize: 13, color: "#241430aa" }}>
      <button type="button" style={{ fontWeight: 700, border: "none", borderRadius: 8, padding: "9px 14px", color: "#241430", cursor: "pointer", background: accent }}>&#10003; {itemLabel}</button>
      <p style={{ margin: "10px 0 0", fontSize: 12 }}>UI updated instantly, before the server replied.</p>
      {confirmed && (
        <p role="status" style={{ margin: "6px 0 0", fontWeight: 600 }}>
          Server confirmed {outcome === "rollback" ? "\u2014 rolled back, action failed" : "\u2014 no change needed"}
        </p>
      )}
      <p style={{ margin: "10px 0 0", fontSize: 11, color: "#241430aa" }}>Optimistic: assume success, then reconcile if the server disagrees</p>
    </div>
  );
}
